window.__JVC_PARTS[27]="';\nfunction resize(){const k=innerWidth/400;c.style.width=400*k+'px';c.style.height=640*k+'px';c.width=Math.round(400*devicePixelRatio);c.height=Math.round(640*devicePixelRatio);ctx.setTransform(c.width/400,0,0,c.height/640,0,0)}addEventListener('resize',resize);resize();\ndocument.querySelectorAll('.card').forEach(el=>el.onclick=()=>{who=el.dataset.id;document.querySelectorAll('.card').forEach(e=>e.classList.toggle('selected',e===el))});\ndocument.getElementById('go').onclick=()=>{document.getElementById('menu').style.display='none';state='running';scroll=0;jump=0;vy=0;phase=1;phaseBanner=0;collided=false;document.getElementById('transition').classList.remove('show')};document.getElementById('continue').onclick=()=>{document.getElementById('transition').classList.remove('show');if(state==='hit'){scroll=0;jump=0;vy=0;collided=false;state='running';return;}phase=2;scroll=0;jump=0;vy=0;state='running';phaseBanner=1.5};const pause=document.getElementById('pause');pause.onclick=()=>{if(state==='running'){state='paused';pause.textContent='SEGUIR ▶'}else if(state==='paused'){state='running';pause.textContent='PAUSA Ⅱ'}else if(state==='hit'){ctx.fillStyle='rgba(100,0,0,.15)';ctx.fillRect(0,0,400,640)}if(state==='done'){state='running';scroll=0;phase=1;phaseBanner=0;collided=false;document.getElementById('transition').classList.remove('show');pause.textContent='PAUSA Ⅱ'}};\nfunction leap(){if(state==='running'&&jump===0){jump=.01;vy=355}}c.addEventListener('pointerdown',leap);addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='ArrowUp'){e.preventDefault();leap()}});\nconst obstacle=new Image();obstacle.src='data:image/png;base64,";